{"implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    # Build map of distances for quick lookup, but also process all pairs given
    # For each pair in distances, compute mutual reachability
    n = len(nodes)
    # Collect all edges with mutual reachability weight
    edges = []
    for u, v, d in dists:
        w = max(core[u], core[v], d)
        # canonical order: u < v lexicographically (strings)
        if u < v:
            edges.append((u, v, w))
        else:
            edges.append((v, u, w))
    # Sort by weight, then smaller node, then larger node (already canonical)
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst.append([u, v, w])
            total += w
            if len(mst) == n - 1:
                break
    if len(mst) != n - 1:
        raise ValueError('Graph is disconnected, cannot form MST')
    return {
        'mst_edges': mst,
        'total_weight': total
    }
